import React, { useState } from "react";
import axios from "axios";

function App() {
  const [form, setForm] = useState({
    client: "",
    industry: "",
    budget: "",
    services: ""
  });

  const [result, setResult] = useState(null);
  const [diff, setDiff] = useState("");

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const generateProposal = async () => {
    const res = await axios.post("http://127.0.0.1:8000/generate", form);
    setResult(res.data);
  };

  const compareVersions = async () => {
    const res = await axios.get(
      `http://127.0.0.1:8000/compare/${form.client}`
    );
    setDiff(res.data.diff);
  };

  return (
    <div style={{ padding: "30px", fontFamily: "Arial" }}>
      <h1>🚀 PropelPro AI</h1>

      {/* FORM */}
      <div style={{ marginBottom: "20px" }}>
        <input name="client" placeholder="Client" onChange={handleChange} />
        <br />
        <input name="industry" placeholder="Industry" onChange={handleChange} />
        <br />
        <input name="budget" placeholder="Budget" onChange={handleChange} />
        <br />
        <textarea
          name="services"
          placeholder="Services"
          onChange={handleChange}
        />
        <br />

        <button onClick={generateProposal}>Generate Proposal</button>
        <button onClick={compareVersions}>Compare Versions</button>
      </div>

      {/* OUTPUT */}
      {result && (
        <div>
          <h2>📄 Proposal</h2>
          <pre>{result.proposal}</pre>

          <h2>🧾 Executive Summary</h2>
          <p>{result.summary}</p>

          <h2>⚠️ Risks & Assumptions</h2>
          <p>{result.risks}</p>
        </div>
      )}

      {/* DIFF */}
      {diff && (
        <div>
          <h2>🔍 Version Comparison</h2>
          <pre>{diff}</pre>
        </div>
      )}
    </div>
  );
}

export default App;
